export const printProductionMarkup="<main id=\"print-production-app\"><header><p class=\"eyebrow\">Print shop operations</p><h1>Quotes, intake and production</h1><p id=\"pp-summary\"></p></header><div class=\"toolbar\"><button type=\"button\" data-action=\"open\">Open project</button><button type=\"button\" data-action=\"save\">Save project</button><button type=\"button\" data-action=\"html\">Save offline app</button><button type=\"button\" data-action=\"zip\">Download whole ZIP</button></div><input id=\"pp-file\" type=\"file\" accept=\".json,application/json\" hidden><label class=\"operator\">Current operator<input id=\"pp-operator\" data-bind=\"operator\" autocomplete=\"name\"></label><p id=\"pp-status\" role=\"status\"></p><p id=\"pp-error\" role=\"alert\" hidden></p><nav id=\"pp-nav\" aria-label=\"Print production panels\"></nav><div id=\"pp-panel\"></div></main>";
