export function renderPrintProductionWorkbench(record,{engineSource,hashSource,zipSource,guide='',sourceFiles={}}={}){
 if(!engineSource||!hashSource||!zipSource)throw new Error('Supply complete engine, hash and ZIP sources.');
 const wrap=(name,code)=>'const '+name+'=(()=>{const module={exports:{}};const exports=module.exports;\n'+code+'\n;return module.exports;})();\n';
 const bootstrap=wrap('PrintProductionHash',hashSource)+wrap('PrintProductionZip',zipSource)+wrap('PrintProductionEngine',engineSource)+'('+printProductionBrowserSource+')();';
 const payload={record,guide,markup:printProductionMarkup,css:printProductionCss,bootstrap,sourceFiles:{
  'print_production_workbench.cjs':engineSource,'connected_sha256.cjs':hashSource,'connected_zip.cjs':zipSource,...sourceFiles},
  sourceOrder:[...new Set(['print_production_workbench.cjs','connected_sha256.cjs','connected_zip.cjs',...Object.keys(sourceFiles)])]};
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Print production</title><style>'+
 printProductionCss+'</style></head><body>'+printProductionMarkup+'<script id="print-production-data" type="application/json">'+JSON.stringify(payload).replace(/</g,'\\u003c')+
 '</script><script>'+bootstrap.replace(/<\/script/gi,'<\\/script')+'</script></body></html>';
}
